WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time ASC, id ASC) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY page ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM with_gaps) SELECT CASE WHEN duration_sec >= 533 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, CASE WHEN session_id_2 >= 9 THEN 'LARGE' ELSE 'SMALL' END AS session_id_2_tier, COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) AS purchase_count, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, COUNT_IF(page = '/home') AS home_events, PERCENTILE_APPROX(is_new_burst, 0.9) AS is_new_burst_p90, PERCENT_RANK() OVER (PARTITION BY CASE WHEN duration_sec >= 533 THEN 'LARGE' ELSE 'SMALL' END ORDER BY PERCENTILE_APPROX(is_new_burst, 0.9) DESC) AS is_new_burst_p90_percent_rank FROM sessionized GROUP BY duration_sec_tier, session_id_2_tier ORDER BY duration_sec_tier DESC NULLS LAST;
